#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
      B[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i*j+3)%n) / m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Transpose B once into a temporary BT so that accesses corresponding
     to B[j][k] become unit-stride (cache-friendly) as BT[k][j].
     This adds at most ~33–50% to the total memory footprint, within
     the allowed limit.
   - Precompute alpha * A[i][k] and alpha * B[i][k] once per (i,k) to
     reduce multiplications inside the innermost loop.
   - Parallelize the outer loop over i with OpenMP; each (i,*) row of C
     is independent, so there are no data races.
   - Keep C row accesses unit-stride and preserve the original
     computation order over (i,j,k).
*/
static
void __attribute__((noinline, flatten))
kernel_syr2k(int n, int m,
	     DATA_TYPE alpha,
	     DATA_TYPE beta,
	     DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
	     DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
	     DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Temporary transpose of B:
     BT has dimensions [M][N] and is defined so that
       BT[k][i] == B[i][k].
     In the original kernel the access B[j][k] is column-wise.
     Using BT[k][j] instead makes that access row-wise and
     cache-friendly, while still respecting the 50% memory
     overhead constraint. */
  POLYBENCH_2D_ARRAY_DECL(BT, DATA_TYPE, M, N, m, n);

  /* Build BT = B^T.
     We only need the subset actually touched by the kernel:
     i in [0, _PB_N), k in [0, _PB_M). */
  for (i = 0; i < _PB_N; i++)
    for (k = 0; k < _PB_M; k++)
      BT[k][i] = B[i][k];

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Parallelize over rows of C.
     Each i-iteration updates only C[i][0..i], so iterations are
     independent and safe to execute concurrently. */
#pragma omp parallel for private(j,k) schedule(static)
  for (i = 0; i < _PB_N; i++) {
    const int j_end = i + 1; /* Number of elements in row i's lower triangle. */

    /* Scale C(i,0..i) by beta. This matches the original
       first loop:
         for (j = 0; j <= i; j++) C[i][j] *= beta; */
    for (j = 0; j < j_end; j++)
      C[i][j] *= beta;

    /* Rank-2k update:
         C[i][j] += A[j][k]*alpha*B[i][k] +
                    B[j][k]*alpha*A[i][k];
       We preserve the i–k–j loop order so that A[i][k] and B[i][k]
       are reused across all j in the innermost loop. */
    for (k = 0; k < _PB_M; k++) {
      const DATA_TYPE aik = A[i][k];
      const DATA_TYPE bik = B[i][k];

      /* Precompute alpha*A[i][k] and alpha*B[i][k] once per (i,k),
         instead of recomputing alpha*... for every j. */
      const DATA_TYPE alpha_aik = alpha * aik;
      const DATA_TYPE alpha_bik = alpha * bik;

      /* Inner loop over j:
         - C[i][j] is unit-stride along the row.
         - A[j][k] is a column-wise access (unchanged).
         - BT[k][j] is unit-stride and replaces the original B[j][k]. */
      for (j = 0; j < j_end; j++) {
        C[i][j] += A[j][k] * alpha_bik + BT[k][j] * alpha_aik;
      }
    }
  }
#pragma endscop

  /* Free temporary transpose buffer. */
  POLYBENCH_FREE_ARRAY(BT);
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
