#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* Hoist reciprocals to avoid repeated divisions in the loops. */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;
  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;

  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE)((i * j + 1) % n) * inv_n;
      B[i][j] = (DATA_TYPE)((i * j + 2) % m) * inv_m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE)((i * j + 3) % n) * inv_m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Create restrict-qualified views of the matrices to enable better
     alias analysis without changing the external interface. The
     PolyBench harness always passes three distinct arrays here, so
     the restrict assumptions are valid. */
  DATA_TYPE (*restrict C_)[n] = (DATA_TYPE (*)[n]) C;
  DATA_TYPE (*restrict A_)[m] = (DATA_TYPE (*)[m]) A;
  DATA_TYPE (*restrict B_)[m] = (DATA_TYPE (*)[m]) B;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Parallelize over i: each iteration updates a distinct row of the
     lower triangular part of C_, so there are no write conflicts.
     If compiled without OpenMP support, this pragma is ignored. */
  #pragma omp parallel for private(j, k) schedule(static)
  for (i = 0; i < _PB_N; i++) {
    /* Row pointers for faster and clearer indexing. These are
       restrict-qualified to help the compiler vectorize. */
    DATA_TYPE       *restrict Ci = C_[i];
    const DATA_TYPE *restrict Ai = A_[i];
    const DATA_TYPE *restrict Bi = B_[i];

    /* Only the lower triangular part (j <= i) is referenced. */
    for (j = 0; j <= i; j++) {
      const DATA_TYPE *restrict Aj = A_[j];
      const DATA_TYPE *restrict Bj = B_[j];

      /* Fuse the original separate beta scaling and the subsequent
         rank-2k accumulation into a single pass over C[i][j].
         This reduces memory traffic on C from O(M) loads/stores per
         element to O(1), and improves cache efficiency. */
      DATA_TYPE cij = Ci[j] * beta_local;

      /* Compute:
           cij += alpha * sum_k (Aj[k]*Bi[k] + Bj[k]*Ai[k]);

         The inner loop walks the k dimension (row-major contiguous)
         for all four matrices, which improves spatial locality and
         enables efficient vectorization. */
      for (k = 0; k < _PB_M; k++) {
        const DATA_TYPE Aik = Ai[k];
        const DATA_TYPE Ajk = Aj[k];
        const DATA_TYPE Bik = Bi[k];
        const DATA_TYPE Bjk = Bj[k];

        cij += alpha_local * (Ajk * Bik + Bjk * Aik);
      }

      Ci[j] = cij;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
