		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Cache scalar parameters locally so the compiler can keep them
     in registers and so we can refer to them explicitly. */
  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Parallelize the outer i-loop.  Each (i, j) pair writes a distinct
     element C[i][j], and A/B are read-only, so there are no data races.
     If OpenMP is not enabled, the pragma is ignored by the compiler. */
#ifdef _OPENMP
  #pragma omp parallel for private(j, k) schedule(static)
#endif
  for (i = 0; i < _PB_N; i++) {

    /* Row pointers for the current i.  Using explicit row pointers
       reduces address arithmetic in the inner loops. */
    DATA_TYPE *Ci = C[i];
    DATA_TYPE *Ai = A[i];
    DATA_TYPE *Bi = B[i];

    /* Fused version of the original two j-loops:
         1. C[i][j] *= beta
         2. for k: C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
       For each (i,j) we perform the multiply by beta followed by the
       k-accumulation in exactly the same order as the original code,
       but we keep C[i][j] in a scalar register for the whole update. */
    for (j = 0; j <= i; j++) {
      /* Step 1: scale by beta (done once, kept in register). */
      DATA_TYPE cij = Ci[j] * beta_;

      /* Row pointers for index j.  With k as the innermost loop,
         Aj[k] and Bj[k] are accessed contiguously in memory, which
         improves cache locality and SIMD vectorization. */
      DATA_TYPE *Aj = A[j];
      DATA_TYPE *Bj = B[j];

      /* Step 2: rank-2k update accumulated in a register.
         The arithmetic expression is kept in the same
         associative form as the original:
           (A[j][k]*alpha*B[i][k]) + (B[j][k]*alpha*A[i][k])
         to preserve floating-point semantics. */
      for (k = 0; k < _PB_M; k++) {
        const DATA_TYPE ajk = Aj[k];
        const DATA_TYPE bik = Bi[k];
        const DATA_TYPE bjk = Bj[k];
        const DATA_TYPE aik = Ai[k];

        cij += ((ajk * alpha_) * bik) +
               ((bjk * alpha_) * aik);
      }

      /* Single write-back of the updated element. */
      Ci[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
