/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Fuse the beta-scaling of C with the rank-2k update so that each
     C[i][j] is loaded and stored only once.
   - Change the loop order to make the k loop innermost. This makes
     accesses Aj[k] and Bj[k] contiguous in memory (row-major layout),
     improving cache locality for A and B.
   - Precompute alpha * A[i][k] and alpha * B[i][k] once per row i and
     reuse these values for all j, removing redundant multiplications
     from the innermost loop.
   - Parallelize the outer loop over i with OpenMP; each iteration
     updates a distinct row of the lower-triangular part of C, so
     there are no cross-iteration write conflicts.
*/
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Use PolyBench's possibly adjusted problem sizes. */
  const int nn = _PB_N;
  const int mm = _PB_M;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Parallelize across rows of C. */
  #pragma omp parallel private(j,k)
  {
    /* Thread-local temporaries for alpha-scaled versions of row i of A and B.
       Size depends only on mm (= _PB_M) and is reused for all rows handled
       by this thread. */
    DATA_TYPE alphaAi[mm];
    DATA_TYPE alphaBi[mm];

    #pragma omp for schedule(static)
    for (i = 0; i < nn; i++)
    {
      /* Pointer to the current row of C.
         Marked restrict because C does not alias A or B. */
      DATA_TYPE *restrict Ci = C[i];

      /* Precompute alpha * A[i][k] and alpha * B[i][k] once per row i.
         The original code computed these products inside the innermost
         loop, redundantly for every (i,j,k). */
      {
        const DATA_TYPE *Ai = A[i];
        const DATA_TYPE *Bi = B[i];

        for (k = 0; k < mm; k++)
        {
          alphaAi[k] = alpha * Ai[k];
          alphaBi[k] = alpha * Bi[k];
        }
      }

      /* Update the lower-triangular part of C: 0 <= j <= i. */
      for (j = 0; j <= i; j++)
      {
        const DATA_TYPE *Aj = A[j];
        const DATA_TYPE *Bj = B[j];

        /* Start from beta-scaled value of C[i][j].
           This fuses the separate scaling loop into the update loop. */
        DATA_TYPE cij = Ci[j] * beta;

        /* Accumulate rank-2k update for this (i,j) over k.
           Inner loop on k improves spatial locality for Aj[k] and Bj[k]
           (row-major layout).  The accumulation order in k matches
           the original kernel; only the factorization of alpha and
           loop nesting have changed. */
        for (k = 0; k < mm; k++)
        {
          cij += Aj[k] * alphaBi[k] + Bj[k] * alphaAi[k];
        }

        Ci[j] = cij;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
